package vn.svframe.svframemmo.script.mechanic;
import net.minecraft.entity.Entity;import net.minecraft.server.network.ServerPlayerEntity;import vn.svframe.svframelib.player.resource.ResourceUpdateReason;import vn.svframe.svframelib.script.mechanic.type.TargetMechanic;import vn.svframe.svframelib.script.util.expression.numeric.NumericExpression;import vn.svframe.svframelib.skill.SkillMetadata;import vn.svframe.svframelib.util.configobject.ConfigObject;import vn.svframe.svframemmo.SVFrameMMO;import vn.svframe.svframemmo.api.player.profess.resource.PlayerResource;
public final class StaminaMechanic extends TargetMechanic {private final NumericExpression amount;private final Operation operation;private final ResourceUpdateReason reason;public StaminaMechanic(ConfigObject c){super(c);amount=c.numericExpr("amount");operation=c.contains("operation")?Operation.valueOf(c.getString("operation").toUpperCase()):Operation.GIVE;reason=c.contains("reason")?ResourceUpdateReason.valueOf(c.getString("reason").toUpperCase()):ResourceUpdateReason.MECHANIC;}public void cast(SkillMetadata meta,Entity target){if(!(target instanceof ServerPlayerEntity p))throw new IllegalArgumentException("Target is not a player");var d=SVFrameMMO.playerData().get(p);double a=amount.evaluate(meta);PlayerResource r=PlayerResource.STAMINA;switch(operation){case GIVE->r.give(d,a,reason);case TAKE->r.give(d,-a,reason);case SET->r.setCurrent(d,a,reason);}}}
